#!/bin/sh
# Generate generated/greeting.go from spec.txt.
set -eu
cd "$(dirname "$0")"
greeting="$(sed -n 's/^greeting=//p' spec.txt)"
mkdir -p generated
printf '%s\n' \
	'// Code generated by gen.sh from spec.txt. DO NOT EDIT.' \
	'' \
	'// Package generated holds values gen.sh writes from spec.txt.' \
	'package generated' \
	'' \
	'// Greeting is the text the program prints.' \
	"const Greeting = \"${greeting}\"" >generated/greeting.go
